const MAN = { 'janúar': 'January', 'febrúar': 'February', 'mars': 'March', 'apríl': 'April', 'maí': 'May', 'júní': 'June',
  'júlí': 'July', 'ágúst': 'August', 'september': 'September', 'október': 'October', 'nóvember': 'November', 'desember': 'December',
  'jan': 'Jan', 'feb': 'Feb', 'mar': 'Mar', 'apr': 'Apr', 'jún': 'Jun', 'júl': 'Jul', 'ágú': 'Aug', 'sep': 'Sep', 'okt': 'Oct', 'nóv': 'Nov', 'des': 'Dec' };
const DAGAR = { 'sunnudagur': 'Sunday', 'mánudagur': 'Monday', 'þriðjudagur': 'Tuesday', 'miðvikudagur': 'Wednesday',
  'fimmtudagur': 'Thursday', 'föstudagur': 'Friday', 'laugardagur': 'Saturday',
  'sunnudaginn': 'Sunday', 'mánudaginn': 'Monday', 'þriðjudaginn': 'Tuesday', 'miðvikudaginn': 'Wednesday',
  'fimmtudaginn': 'Thursday', 'föstudaginn': 'Friday', 'laugardaginn': 'Saturday',
  'sun': 'Sun', 'mán': 'Mon', 'þri': 'Tue', 'mið': 'Wed', 'fim': 'Thu', 'fös': 'Fri', 'lau': 'Sat' };
/* Líka með stórum staf fremst (t.d. "Nóvember 2026" í haus dagatalsins) */
const storFremst = (o) => { for (const [k, v] of Object.entries(o)) o[k.charAt(0).toUpperCase() + k.slice(1)] = v; return o; };
storFremst(MAN); storFremst(DAGAR);

const har = (o, k) => Object.prototype.hasOwnProperty.call(o, k);
const STAFUR = /[\p{L}\p{N}]/u;
const erStafur = (c) => !!c && STAFUR.test(c);

/* Orðabók fyrir brot: flett upp eftir fyrsta orði (eða fyrsta tákni),
   lengsti lykill fyrst. Kostnaðurinn fer eftir lengd textans, ekki stærð orðabókarinnar. */
function smidaVisi(ord) {
  const visir = new Map();
  for (const k of Object.keys(ord)) {
    const m = /^[\p{L}\p{N}]+/u.exec(k);
    const lykill = m ? m[0] : k.charAt(0);
    if (!visir.has(lykill)) visir.set(lykill, []);
    visir.get(lykill).push(k);
  }
  for (const listi of visir.values()) listi.sort((a, b) => b.length - a.length);
  return visir;
}
/* Þýddir bútar eru merktir svo seinni umferð þýði ekki enska orðið aftur (t.d. Send) */
const VERJA_FRA = '\u0001', VERJA_TIL = '\u0002';
function skipta(t, ord, visir, verja) {
  let ut = '', i = 0;
  while (i < t.length) {
    const c = t.charAt(i);
    if (c === VERJA_FRA) { const e = t.indexOf(VERJA_TIL, i); const lok = e < 0 ? t.length : e + 1; ut += t.slice(i, lok); i = lok; continue; }
    let lykill, lengd;
    if (erStafur(c)) {
      if (erStafur(t.charAt(i - 1))) { ut += c; i++; continue; }
      const m = /^[\p{L}\p{N}]+/u.exec(t.slice(i, i + 60));
      lykill = m[0]; lengd = lykill.length;
    } else { lykill = c; lengd = 1; }
    let fundid = null;
    for (const k of visir.get(lykill) || []) {
      if (t.startsWith(k, i) && !(erStafur(k.charAt(k.length - 1)) && erStafur(t.charAt(i + k.length)))) { fundid = k; break; }
    }
    if (fundid) { ut += verja ? VERJA_FRA + ord[fundid] + VERJA_TIL : ord[fundid]; i += fundid.length; } else { ut += t.slice(i, i + lengd); i += lengd; }
  }
  return ut;
}

const FJOL_ORD = {}, STOK_ORD = {};
for (const k of Object.keys(ORD)) {
  if (/\s/.test(k)) { if (k.length >= 5) FJOL_ORD[k] = ORD[k]; continue; }
  if (k.length < 3) continue;
  STOK_ORD[k] = ORD[k];
  /* Líka með litlum staf fremst ("3 verkefni" eins og "Verkefni") */
  const lagt = k.charAt(0).toLowerCase() + k.slice(1);
  if (!har(STOK_ORD, lagt)) STOK_ORD[lagt] = ORD[k].charAt(0).toLowerCase() + ORD[k].slice(1);
}
const FJOL_VISIR = smidaVisi(FJOL_ORD), STOK_VISIR = smidaVisi(STOK_ORD);
const MAN_STAKT = Object.fromEntries(Object.entries(MAN).filter(([k]) => k.length > 3));
const MAN_VISIR = smidaVisi(MAN_STAKT), DAG_VISIR = smidaVisi(DAGAR);
const MAN_NAFN = Object.keys(MAN).join('|');
const MAN_RE = new RegExp('(?<![\\p{L}\\p{N}])(\\d{1,2})\\.\\s(' + MAN_NAFN + ')\\.?(?![\\p{L}\\p{N}])', 'gu');
const KL = /(?<![\p{L}\p{N}])kl\.\s?(?=\d)/gu;
const MAN_AR = new RegExp('(?<![\\p{L}\\p{N}])(' + MAN_NAFN + ')\\.?(?=\\s\\d{4})', 'gu');

/* Mynstur þar sem tala eða nafn er skeytt við texta */
const THUS = /(\d+) þ\./gu;
const A_EININGU = /((?:[€$]\s?)?\d[\d.,]*(?:\s?(?:ISK|kr\.|€|\$))?) á (\p{L}+)(?![\p{L}])/gu;
const A_ARI = / á ári(?![\p{L}])/gu;
const FORSKEYTI = [[/^fyrir (?=\p{Lu})/u, 'for '], [/^Frá (?=\p{Lu})/u, 'From '], [/^Á (?=\p{Lu})/u, 'To '], [/^Til (?=\p{Lu})/u, 'To '],
  [/^Hæ (?=\p{Lu})/u, 'Hi '], [/^Viðskiptavinur hjá /u, 'Client at '], [/^hjá (?=\p{Lu})/u, 'at '], [/^frá (?=\p{Lu}|\d)/u, 'from '],
  [/^Eftir (?=\d)/u, 'In '], [/^Til (?=\S+@)/u, 'To '], [/^Fyrir (?=\S+@)/u, 'For '], [/^Ef (?=\S+@)/u, 'If ']];
/* Tengiorð á milli talna og dagsetninga, keyrt eftir að mánuðirnir eru þýddir */
const EN_MAN = 'January|February|March|April|May|June|July|August|September|October|November|December|Jan|Feb|Mar|Apr|Jun|Jul|Aug|Sep|Oct|Nov|Dec';
const TENGI = [
  [new RegExp(' í (?=(?:' + EN_MAN + ')(?![\\p{L}]))', 'gu'), ' in '],
  [/(\d) í (?=[-+]?\d)/gu, '$1 to '],
  [new RegExp('(\\d|' + EN_MAN + ') til (?=\\d|' + EN_MAN + ')', 'gu'), '$1 to '],
  [/(^|[\s:,(]) ?frá (?=[-+]?\d)/gu, '$1from '],
  [/(\d) áhorf(?![\p{L}])/gu, '$1 views'],
  [/(\d) líkar(?![\p{L}])/gu, '$1 likes'],
  [/(\d) alls(?![\p{L}])/gu, '$1 total'],
  [/(\d) (?:myndbönd|vidjó)(?![\p{L}])/gu, '$1 videos'],
  [/(?<![\p{L}])myndband (?=\d)/gu, 'video '],
  [/(\d) af (?=\d)/gu, '$1 of '],
  [/(\d) (?:daga|dagar)(?![\p{L}])/gu, '$1 days'],
  [/(?<![\d])1 (?:dag|dagur)(?![\p{L}])/gu, '1 day'],
  [/(\d) (?:dag|dagur)(?![\p{L}])/gu, '$1 days'],
  [/(\d) skrefum(?![\p{L}])/gu, '$1 steps'],
  [/(?<![\d])1 klst\./gu, '1 hr'],
  [/(\d) klst\./gu, '$1 hrs'],
  [/(\d) mín\./gu, '$1 min'],
  [/(\d) stk\./gu, '$1 items']
];

function dagsetningar(t) {
  if (/\d/.test(t)) t = t.replace(MAN_RE, (_, dd, m) => dd + ' ' + MAN[m]).replace(MAN_AR, (_, m) => MAN[m]).replace(KL, 'at ').replace(THUS, '$1k')
    .replace(A_ARI, ' per year').replace(A_EININGU, (_, upph, ein) => upph + ' per ' + (ORD[ein] || STOK_ORD[ein] || ein));
  return skipta(skipta(t, MAN_STAKT, MAN_VISIR), DAGAR, DAG_VISIR);
}
function tengiord(t) { for (const [re, en] of TENGI) t = t.replace(re, en); return t; }

/* Nákvæm samsvörun, líka með greinarmerki aftast (t.d. "Nafn:") */
function nakvaemt(x) {
  if (har(ORD, x)) return ORD[x];
  const m = x.match(/^([\s\S]*?)([:.!?,…*]+)$/);
  if (m && har(ORD, m[1])) return ORD[m[1]] + m[2];
  return null;
}

/* Langur texti er nær alltaf efni sem notendur skrifuðu: bara nákvæm samsvörun */
const HAMARK_BROTA = 400;
const minni = new Map();
function thyda(t, varlegt) {
  const lykill = (varlegt ? '1' : '0') + t;
  if (minni.has(lykill)) return minni.get(lykill);
  const ut = thydaBeint(t, varlegt);
  if (minni.size > 5000) minni.clear();
  minni.set(lykill, ut);
  return ut;
}
function thydaBeint(t, varlegt) {
  const m = /^(\s*)([\s\S]*?)(\s*)$/.exec(t);
  const x = m[2];
  if (!x || !/\p{L}/u.test(x)) return t;
  const n = nakvaemt(x);
  if (n !== null) return m[1] + n + m[3];
  if (varlegt || x.length > HAMARK_BROTA) return t;
  let y = skipta(x, FJOL_ORD, FJOL_VISIR, true);
  y = dagsetningar(y);
  for (const [re, en] of FORSKEYTI) y = y.replace(re, en);
  /* Stök orð bara í stuttum texta með tölu, t.d. "3 verkefni" eða "12 taskar" */
  if (/\d/.test(y) && y.split(/\s+/).length <= 4) y = skipta(y, STOK_ORD, STOK_VISIR);
  if (/\d/.test(y)) y = tengiord(y);
  return m[1] + y.replace(/[\u0001\u0002]/g, '') + m[3];
}

/* Undirskriftin í forskoðun fer út á íslensku, svo hún er sýnd eins og hún verður send */
const SLEPPA = 'script,style,textarea,code,pre,[data-ekki-thyda],[contenteditable=""],[contenteditable="true"],.sk-undirsk > :not(.skyring)';
/* Placeholder og title á textareitum eru viðmót, bara efnið sjálft er látið vera */
const SLEPPA_EIGINLEIKA = '[data-ekki-thyda],[contenteditable=""],[contenteditable="true"]';
const VARLEGT = '.sk-sb__texti,.sk-sb__efni,.sk-thradur__efni,.sk-lina__snid,.sk-lina__efni';
const EIGINLEIKAR = ['placeholder', 'title', 'aria-label', 'alt'];
const buid = new WeakMap(), buidEig = new WeakMap();

function textanod(n) {
  const v = n.nodeValue;
  if (!v || buid.get(n) === v) return;
  const f = n.parentElement;
  if (!f || f.closest(SLEPPA)) { buid.set(n, v); return; }
  const t = thyda(v, !!f.closest(VARLEGT));
  buid.set(n, t);
  if (t === v) return;
  /* Valmöguleiki án value les textann sinn: festum íslenska gildið svo enska fari ekki í gögnin */
  if (f.tagName === 'OPTION' && !f.hasAttribute('value')) f.setAttribute('value', f.value);
  n.nodeValue = t;
}

function eiginleikar(e) {
  if (e.closest(SLEPPA_EIGINLEIKA)) return;
  let skrad = buidEig.get(e);
  for (const a of EIGINLEIKAR) {
    const v = e.getAttribute(a);
    if (!v || (skrad && skrad[a] === v)) continue;
    const t = thyda(v, false);
    if (!skrad) { skrad = {}; buidEig.set(e, skrad); }
    skrad[a] = t;
    if (t !== v) e.setAttribute(a, t);
  }
  if (e.tagName === 'INPUT' && /^(button|submit|reset)$/i.test(e.type) && e.value && !(skrad && skrad.value === e.value)) {
    const t = thyda(e.value, false);
    if (!skrad) { skrad = {}; buidEig.set(e, skrad); }
    skrad.value = t;
    if (t !== e.value) e.value = t;
  }
}

function fara(rot) {
  if (rot.nodeType === 3) { textanod(rot); return; }
  if (rot.nodeType !== 1 && rot.nodeType !== 9) return;
  if (rot.nodeType === 1) eiginleikar(rot);
  const w = document.createTreeWalker(rot, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT);
  for (let n = w.nextNode(); n; n = w.nextNode()) {
    if (n.nodeType === 3) textanod(n); else eiginleikar(n);
  }
}

document.documentElement.lang = 'en';
fara(document);

new MutationObserver((breytingar) => {
  for (const b of breytingar) {
    if (b.type === 'characterData') textanod(b.target);
    else if (b.type === 'attributes') eiginleikar(b.target);
    else b.addedNodes.forEach(fara);
  }
}).observe(document.documentElement, { subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: EIGINLEIKAR });

/* Spurningar og tilkynningar úr kóðanum (confirm, alert, prompt) */
for (const f of ['confirm', 'alert', 'prompt']) {
  const upph = window[f].bind(window);
  window[f] = (texti, ...rest) => upph(typeof texti === 'string' ? thyda(texti, false) : texti, ...rest);
}

export { thyda };
